document.addEventListener("DOMContentLoaded", () => { const e = document.querySelector(".toggle-password"), t = document.querySelector(".password-wrapper input"); e && t && e.addEventListener("click", () => { const l = "password" === t.getAttribute("type") ? "text" : "password"; t.setAttribute("type", l), e.innerHTML = "password" === l ? '<i class="far fa-eye"></i>' : '<i class="far fa-eye-slash"></i>' }); const l = document.querySelectorAll(".meal-item"); l.forEach(e => { e.addEventListener("click", () => { l.forEach(e => e.classList.remove("selected")), e.classList.add("selected") }) }); const s = document.querySelectorAll(".nav-item"); s.forEach(e => { e.addEventListener("click", () => { s.forEach(e => e.classList.remove("active")), e.classList.add("active") }) }) });